<?php
declare(strict_types=1);
require_once __DIR__.'/auth_check.php';require_once __DIR__.'/role_check.php';require_once __DIR__.'/db.php';
$meetingId=max(1,(int)($_GET['meeting_id']??$_POST['meeting_id']??0));$user=(int)($_SESSION['user_id']??0);$meetingStmt=$conn->prepare("SELECT m.*,c.committee_name,c.chair_staff_id,chair.full_name chair_name FROM committee_meetings m JOIN committees c ON c.id=m.committee_id LEFT JOIN program_staff chair ON chair.id=c.chair_staff_id WHERE m.id=:meeting AND c.committee_name='Consultancy Committee'");$meetingStmt->execute([':meeting'=>$meetingId]);$meeting=$meetingStmt->fetch();if(!$meeting){http_response_code(404);exit('Consultancy committee meeting not found.');}$staffStmt=$conn->prepare("SELECT id,full_name FROM program_staff WHERE user_id=:user AND employment_status='Active' LIMIT 1");$staffStmt->execute([':user'=>$user]);$currentStaff=$staffStmt->fetch();$currentStaffId=(int)($currentStaff['id']??0);$isChair=$currentStaffId>0&&$currentStaffId===(int)$meeting['chair_staff_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){$action=(string)($_POST['action']??'');$conn->beginTransaction();try{if($action==='sign'){$attendance=(int)($_POST['attendance_id']??0);if(!$currentStaffId)throw new RuntimeException('Your account must be linked to an active staff record before signing.');$s=$conn->prepare("UPDATE committee_meeting_attendance SET attendance_status=:status,signature_name=:name,signed_at=NOW() WHERE id=:attendance AND meeting_id=:meeting AND staff_id=:staff AND attendance_status IN('Invited','Present','Online','Late')");$status=in_array($_POST['attendance_status']??'',['Present','Online','Late'],true)?$_POST['attendance_status']:'Present';$s->execute([':status'=>$status,':name'=>$currentStaff['full_name'],':attendance'=>$attendance,':meeting'=>$meetingId,':staff'=>$currentStaffId]);if($s->rowCount()!==1)throw new RuntimeException('You may sign only your own invitation.');}elseif($action==='approve_attendance'){if(!$isChair)throw new RuntimeException('Only the appointed committee head may certify attendance.');$counts=$conn->prepare("SELECT COUNT(*) invited,SUM(CASE WHEN attendance_status IN('Present','Online','Late') AND signed_at IS NOT NULL THEN 1 ELSE 0 END) signed_present FROM committee_meeting_attendance WHERE meeting_id=:meeting");$counts->execute([':meeting'=>$meetingId]);$c=$counts->fetch();$required=(int)floor((int)$c['invited']/2)+1;if((int)$c['signed_present']<$required)throw new RuntimeException("Attendance cannot be approved: $required signed participants are required.");$s=$conn->prepare('UPDATE committee_meetings SET quorum_met=1,required_quorum_count=:required,attendance_approved_by_staff_id=:chair,attendance_approved_at=NOW() WHERE id=:meeting');$s->execute([':required'=>$required,':chair'=>$currentStaffId,':meeting'=>$meetingId]);}else throw new RuntimeException('Invalid attendance action.');QualitySystem\Security\AuditLogger::record($conn,'consultancy_attendance_'.$action,'allowed','Committees',[],'committee_meeting',$meetingId);$conn->commit();header('Location: /consultancy_attendance_approval.php?meeting_id='.$meetingId);exit;}catch(Throwable$e){if($conn->inTransaction())$conn->rollBack();$error=$e->getMessage();}}
$rowsStmt=$conn->prepare('SELECT a.*,s.full_name,s.academic_rank FROM committee_meeting_attendance a JOIN program_staff s ON s.id=a.staff_id WHERE a.meeting_id=:meeting ORDER BY s.full_name');$rowsStmt->execute([':meeting'=>$meetingId]);$rows=$rowsStmt->fetchAll();$invited=count($rows);$required=(int)floor($invited/2)+1;$signed=count(array_filter($rows,fn($r)=>in_array($r['attendance_status'],['Present','Online','Late'],true)&&$r['signed_at']));$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Attendance certification</title><link rel="stylesheet" href="/assets/style.css"><style>main{max-width:1100px;margin:auto;padding:1rem}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:1rem}.tile{padding:1rem;background:#eef2f5;border-radius:8px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ccd3da;padding:.7rem}.approved{color:#176b32;font-weight:700}@media(max-width:700px){.summary{grid-template-columns:1fr}}</style></head><body><?php require __DIR__.'/nav.php';?><main><p><a href="/consultancy_committee.php">← Consultancy committee</a></p><h1>Attendance Certification</h1><h2><?=$h($meeting['meeting_title'])?></h2><?php if(isset($error)):?><p role="alert"><?=$h($error)?></p><?php endif;?><div class="summary"><div class="tile"><strong><?=$invited?></strong><br>Invited</div><div class="tile"><strong><?=$required?></strong><br>Required: half + 1</div><div class="tile"><strong><?=$signed?></strong><br>Signed present</div><div class="tile"><strong><?=$meeting['attendance_approved_at']?'Approved':'Pending'?></strong><br>Head certification</div></div><p>Committee head: <?=$h($meeting['chair_name']?:'Not assigned')?>. Each member must sign using their own linked staff account.</p><table><thead><tr><th>Member</th><th>Status</th><th>Signature</th><th>Action</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=$h($r['full_name'])?><br><?=$h($r['academic_rank'])?></td><td><?=$h($r['attendance_status'])?></td><td><?=$r['signed_at']?'<span class="approved">'.$h($r['signature_name']).'<br>'.$h($r['signed_at']).'</span>':'Not signed'?></td><td><?php if((int)$r['staff_id']===$currentStaffId&&!$r['signed_at']&&!$meeting['attendance_approved_at']):?><form method="post"><?=csrfField()?><input type="hidden" name="meeting_id" value="<?=$meetingId?>"><input type="hidden" name="attendance_id" value="<?=(int)$r['id']?>"><input type="hidden" name="action" value="sign"><select name="attendance_status"><option>Present</option><option>Online</option><option>Late</option></select><button>Sign my attendance</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php if($isChair&&!$meeting['attendance_approved_at']):?><form method="post"><?=csrfField()?><input type="hidden" name="meeting_id" value="<?=$meetingId?>"><input type="hidden" name="action" value="approve_attendance"><button <?=$signed<$required?'disabled':''?>>Approve attendance as committee head</button></form><?php endif;?><?php if($meeting['attendance_approved_at']):?><p class="approved">Attendance certified on <?=$h($meeting['attendance_approved_at'])?>. Required quorum: <?=(int)$meeting['required_quorum_count']?>.</p><?php endif;?></main></body></html>
